---RefreshBoardByContent 根据标题和内容刷新提示板
---@param titleText string 标题文字
---@param data table 队伍数据
function CommonTipsBoardTeam:RefreshBoardByContent(data, titleText, questId, playerName)
	self._questId = checkNumber(questId)
	self._questType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
	self._playerName = checkString(playerName)

	if not titleText then
		titleText = localize("队伍配置")
	end
	--标题
	local mb = GetLuaBehaviour(self.CommonTitleNode.gameObject, TitleNodePath)
	if not isNull(mb) then
		if not KTool.IsNull(mb.Env) then
			---@type CommonTitleNode
			local env = mb.Env
			env:RefreshUI(titleText)
		end
	end

	CfUtils.FillText(self.Bg.transform:Find("TitleBgNode/PlayerGroup/ImgBgPlayerName/Text"), playerName)
	self:FillTeams(data)
end

function CommonTipsBoardTeam:FillTeams(data)
	if isNull(data) then
		data = {
			{},
		}
	--死的 最多三个
	--elseif table.count(data) < 3 and (
	--	self._questType ~= Constants.IDType.QuestTrainField and
	--	self._questId ~= Constants.SpecialQuestId.LadderId
	--) then
	--	for i = table.count(data) + 1, 3 do
	--		table.insert(data, {})
	--	end
	end	

	for i = 1, #data do
		local t = data[i]
		local go = self.TeamsNode.transform:Find("TeamNode"..i)
		if  not go then
			go = CfUtils.InstantiateGo(self.TeamNode1, self.TeamsNode)
			go.name = "TeamNode"..i
		end
		KTool.SetActive(go, true)

		local env = CfUtils.GetLuaScr(go,TeamNodePath)
		if env then
			env:FillTeam(go,t,i,self._questType,self.excludeDialogs,self._questId)
		end
	end
	self.TeamsNode.sizeDelta = Vector2(self.TeamsNode.sizeDelta.x, 190 * table.count(data))
end

function CommonTipsBoardTeam:SetExcludeDialogs(ids)
	self.excludeDialogs = ids
end



return CommonTipsBoardTeam